public class SemanticVersionTagTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    static String sign(int value) {
        if (value < 0) {
            return "negative";
        }
        if (value > 0) {
            return "positive";
        }
        return "zero";
    }

    public static void main(String[] args) {
        check("parse reads the three numbers", "2|0|13",
                safe(() -> {
                    SemanticVersionTag v = SemanticVersionTag.parse("2.0.13");
                    return v.getMajor() + "|" + v.getMinor() + "|" + v.getPatch();
                }));
        check("toString", "2.0.13", safe(() -> SemanticVersionTag.parse("2.0.13").toString()));
        check("label", "v2.0.13", safe(() -> SemanticVersionTag.parse("2.0.13").label()));
        check("inherited bracketed default", "[v2.0.13]",
                safe(() -> SemanticVersionTag.parse("2.0.13").bracketed()));
        check("minor numbers compare numerically, not alphabetically", "negative",
                safe(() -> sign(SemanticVersionTag.parse("1.2.3").compareTo(SemanticVersionTag.parse("1.10.0")))));
        check("major beats everything", "positive",
                safe(() -> sign(SemanticVersionTag.parse("2.0.0").compareTo(SemanticVersionTag.parse("1.99.99")))));
        check("patch breaks the final tie", "negative",
                safe(() -> sign(SemanticVersionTag.parse("1.0.1").compareTo(SemanticVersionTag.parse("1.0.2")))));
        check("identical versions compare equal", "zero",
                safe(() -> sign(new SemanticVersionTag(3, 4, 5).compareTo(new SemanticVersionTag(3, 4, 5)))));

        java.util.List<SemanticVersionTag> shuffled = new java.util.ArrayList<>(java.util.Arrays.asList(
                new SemanticVersionTag(1, 10, 0),
                new SemanticVersionTag(2, 0, 13),
                new SemanticVersionTag(1, 0, 0),
                new SemanticVersionTag(2, 0, 0),
                new SemanticVersionTag(1, 2, 3)));
        check("sorting a shuffled list", "[1.0.0, 1.2.3, 1.10.0, 2.0.0, 2.0.13]",
                safe(() -> {
                    java.util.Collections.sort(shuffled);
                    return shuffled.toString();
                }));
        check("Collections.max", "2.0.13",
                safe(() -> java.util.Collections.max(shuffled).toString()));

        java.util.List<String> labels = new java.util.ArrayList<>();
        for (SemanticVersionTag tag : shuffled) {
            labels.add(tag.bracketed());
        }
        check("labels follow the sorted order",
                "[[v1.0.0], [v1.2.3], [v1.10.0], [v2.0.0], [v2.0.13]]",
                safe(labels::toString));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

