interface Labeled {

    String label();

    default String bracketed() {
        return "[" + label() + "]";
    }
}

public class SemanticVersionTag implements Comparable<SemanticVersionTag>, Labeled {

    private final int major;
    private final int minor;
    private final int patch;

    public SemanticVersionTag(int major, int minor, int patch) {
        this.major = major;
        this.minor = minor;
        this.patch = patch;
    }

    public static SemanticVersionTag parse(String text) {
        String[] parts = text.split("\\.");
        return new SemanticVersionTag(Integer.parseInt(parts[0]),
                Integer.parseInt(parts[1]),
                Integer.parseInt(parts[2]));
    }

    public int getMajor() {
        return major;
    }

    public int getMinor() {
        return minor;
    }

    public int getPatch() {
        return patch;
    }

    @Override
    public String label() {
        return "v" + toString();
    }

    @Override
    public int compareTo(SemanticVersionTag other) {
        if (major != other.major) {
            return Integer.compare(major, other.major);
        }
        if (minor != other.minor) {
            return Integer.compare(minor, other.minor);
        }
        return Integer.compare(patch, other.patch);
    }

    @Override
    public String toString() {
        return major + "." + minor + "." + patch;
    }
}
